import { gsap } from 'gsap';
import { SplitText } from 'gsap/SplitText.js';

export default class textAnim {
  constructor(element) {
    console.log('ca marche');
    gsap.registerPlugin(SplitText);
    this.element = element;
    this.options = {
      repeat: false,
    };

    // gsap.from(this.element, {
    //   duration: 1,
    //   y: '100',
    //   alpha: 0,
    //   delay: 0.25,
    //   ease: 'expo.out',
    // });
    document.fonts.ready.then(this.init.bind(this));
  }
  init() {
    this.setOptions();
    this.split = SplitText.create(this.element, {
      mask: 'chars',
      type: 'chars, words, lines',
      autoSplit: true,
    });
    this.initAnim();
    this.initObserver();
  }
  initObserver() {
    const observer = new IntersectionObserver(this.watch.bind(this), {
      rootMargin: '0px 0px 0px 0px',
    });
    observer.observe(this.element);
  }
  watch(entries, observer) {
    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i];
      const target = entry.target;
      if (entry.isIntersecting) {
        this.anim(true);
        if (!this.options.repeat) observer.unobserve(target);
      } else {
        this.anim(false);
      }
    }
  }
  initAnim() {
    gsap.set(this.split.chars, {
      filter: 'blur(12px)',
      autoAlpha: 0,
    });
  }
  anim(isAnimIn) {
    const alpha = isAnimIn ? 1 : 0;
    const blur = isAnimIn ? 'blur(0px)' : 'blur(12px)';
    gsap.to(this.split.chars, {
      duration: 1,
      filter: blur,
      autoAlpha: alpha,
      delay: 0.25,
      stagger: { each: 0.05, from: 'start' },
      ease: 'power2.out',
    });
  }

  setOptions() {
    if ('repeat' in this.element.dataset) {
      this.options.repeat = true;
    }
  }
}
