import Swiper from 'swiper/bundle';

export default class Carousel {
  constructor(element) {
    this.element = element;

    this.options = {
      coverflow: true,
      effect: 'coverflow',
      centeredSlides: true,
      slidesPerView: 1,
      coverflowEffect: {
        rotate: 50,
        stretch: 0,
        depth: 100,
        modifier: 1,
        slideShadows: true,
      },
      pagination: {
        el: this.element.querySelector('.swiper-pagination'),
      },
      navigation: {
        nextEl: this.element.querySelector('.swiper-button-next'),
        prevEl: this.element.querySelector('.swiper-button-prev'),
      },
    };

    this.init();
  }

  setOptions() {
    if ('split' in this.element.dataset) {
      this.options.breakpoints = {
        768: {
          slidesPerView: 1.5,
        },
        2000: {
          slidesPerView: 3,
        },
      };
    }

    if ('autoplay' in this.element.dataset) {
      this.options.autoplay = {
        delay: 3000,
        pauseOnMouseEnter: true,
        disableOnInteraction: true,
      };
    }

    if ('loop' in this.element.dataset) {
      this.options.loop = true;
    }

    if ('slides' in this.element.dataset) {
      this.options.slidesPerView = parseFloat(this.element.dataset.slides);
    }
  }

  init() {
    this.setOptions();
    const swiper = new Swiper(this.element, this.options);

    // Position de la souris, mise à jour en continu
    let x = 0;
    let y = 0;

    // Trouve la slide sous la souris et lui met la classe .is-hovered.
    // Nécessaire car Chrome ne recalcule pas :hover après une animation
    // tant que la souris ne bouge pas.
    const refreshHover = () => {
      this.element
        .querySelectorAll('.swiper-slide.is-hovered')
        .forEach((s) => s.classList.remove('is-hovered'));

      const el = document.elementFromPoint(x, y);
      el?.closest('.swiper-slide')?.classList.add('is-hovered');
    };

    window.addEventListener('mousemove', (e) => {
      x = e.clientX;
      y = e.clientY;
      refreshHover();
    });

    // Après chaque animation, on recalcule sans attendre un mouvement
    swiper.on('transitionEnd', refreshHover);
  }
}
